<?php
require_once __DIR__.'/config/customer-auth.php';
require_once __DIR__.'/config/database.php';
require_once __DIR__.'/includes/loyalty.php';
if(!customer_logged_in()){header('Location: '.page_url('login.php?redirect=poin-member.php'));exit;}
$pdo=db();$user=customer_user();$msg='';$err='';
if($pdo){try{loyalty_ensure_tables($pdo);}catch(Throwable $e){}}
if($_SERVER['REQUEST_METHOD']==='POST' && $pdo){
  if(!customer_verify_csrf($_POST['csrf']??''))$err='Permintaan tidak valid.';
  else {[$ok,$m,$code]=loyalty_issue_reward($pdo,(int)$user['id'],(int)($_POST['reward_id']??0)); if($ok)$msg=$m;else$err=$m;}
}
$balance=$pdo?loyalty_balance($pdo,(int)$user['id']):0;$settings=$pdo?loyalty_settings($pdo):['points_per_amount'=>10000,'points_per_order_min'=>0];
$rewards=$pdo?$pdo->query("SELECT * FROM loyalty_rewards WHERE status='active' AND (quota IS NULL OR redeemed_count<quota) ORDER BY points_cost ASC,id DESC")->fetchAll():[];
$hist=[];if($pdo){$q=$pdo->prepare('SELECT * FROM loyalty_transactions WHERE customer_id=? ORDER BY created_at DESC LIMIT 50');$q->execute([(int)$user['id']]);$hist=$q->fetchAll();}
function pm_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Poin Member — Rosa Indah Printing</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><style>
:root{--p:#d64a8a;--ink:#18243a;--muted:#776e76;--line:#eadde4;--soft:#fff4fa;--green:#287a54;--red:#a33b3b}*{box-sizing:border-box}body{margin:0;background:#fbf8fa;color:var(--ink);font-family:Arial,sans-serif}.wrap{max-width:1100px;margin:auto;padding:24px 18px 60px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.brand{font-weight:900;text-decoration:none;color:var(--ink)}.brand span{color:var(--p)}.top a:last-child{border:1px solid var(--line);padding:9px 12px;border-radius:10px;text-decoration:none;color:var(--ink);font-weight:800;font-size:13px}.hero{background:linear-gradient(135deg,#fff,#fff0f7);border:1px solid var(--line);border-radius:22px;padding:25px;display:flex;justify-content:space-between;align-items:center;gap:20px}.hero small{color:var(--p);font-weight:900;letter-spacing:1px}.hero h1{font-size:30px;margin:7px 0}.hero p{color:var(--muted);margin:0}.balance{background:#fff;border:1px solid #f0cede;border-radius:18px;padding:18px 25px;text-align:center;min-width:190px}.balance i{color:var(--p);font-size:25px}.balance strong{display:block;font-size:28px;margin-top:5px}.balance span{font-size:12px;color:var(--muted)}.notice,.err{margin:15px 0;padding:12px 14px;border-radius:11px;font-size:13px}.notice{background:#eefaf4;color:var(--green)}.err{background:#fff0f0;color:var(--red)}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:16px;margin-top:16px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px}.card h2{margin:0 0 5px;font-size:19px}.desc{color:var(--muted);font-size:12px;margin:0 0 16px}.reward{border:1px solid var(--line);border-radius:14px;padding:14px;display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:10px}.reward h3{margin:0 0 5px;font-size:15px}.reward p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.cost{color:var(--p);font-weight:900;white-space:nowrap}.btn{border:0;background:var(--p);color:#fff;padding:9px 11px;border-radius:9px;font-weight:800;cursor:pointer;margin-top:7px}.history{display:flex;flex-direction:column;gap:9px}.tx{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #f0e6eb;padding:10px 0}.tx:last-child{border-bottom:0}.tx strong{font-size:13px}.tx small{display:block;color:var(--muted);margin-top:3px}.earn{color:var(--green)}.redeem{color:var(--p)}.empty{padding:25px;text-align:center;color:var(--muted);font-size:13px}.tip{margin-top:15px;padding:12px;border-radius:11px;background:var(--soft);color:#6e626a;font-size:12px;line-height:1.6}@media(max-width:760px){.hero{flex-direction:column;align-items:flex-start}.balance{width:100%;min-width:0}.grid{grid-template-columns:1fr}}@media(max-width:500px){.wrap{padding:12px 10px 40px}.hero{padding:17px}.hero h1{font-size:24px}.card{padding:15px}.reward{align-items:flex-start;flex-direction:column}.cost{white-space:normal}}
</style></head><body><main class="wrap"><div class="top"><a class="brand" href="<?php echo page_url('akun.php'); ?>">ROSA INDAH <span>PRINTING</span></a><a href="<?php echo page_url('akun.php'); ?>"><i class="bi bi-arrow-left"></i> Akun Member</a></div><section class="hero"><div><small>LOYALTY MEMBER</small><h1>Poin & Reward Member 🎁</h1><p>Kumpulkan poin dari pesanan yang selesai dan tukarkan dengan voucher reward.</p></div><div class="balance"><i class="bi bi-star-fill"></i><strong><?php echo number_format($balance,0,',','.'); ?></strong><span>Poin Anda</span></div></section><?php if($msg):?><div class="notice"><i class="bi bi-check-circle"></i> <?php echo pm_e($msg); ?></div><?php endif;?><?php if($err):?><div class="err"><i class="bi bi-exclamation-circle"></i> <?php echo pm_e($err); ?></div><?php endif;?><div class="grid"><section class="card"><h2>Reward Tersedia</h2><p class="desc">Poin ditambahkan setelah pesanan Member berstatus <strong>Selesai</strong>.</p><?php if(!$rewards):?><div class="empty">Belum ada reward yang tersedia.</div><?php else:foreach($rewards as $r):?><article class="reward"><div><h3><?php echo pm_e($r['name']);?></h3><p><?php echo $r['discount_type']==='fixed'?'Voucher Rp'.number_format((float)$r['discount_value'],0,',','.'): 'Voucher diskon '.rtrim(rtrim(number_format((float)$r['discount_value'],2,',','.'),'0'),',').'%';?><?php if((float)$r['min_order']>0):?> · Min. Rp<?php echo number_format((float)$r['min_order'],0,',','.');?><?php endif;?> · Berlaku <?php echo (int)$r['validity_days'];?> hari</p><div class="cost"><?php echo number_format((int)$r['points_cost'],0,',','.');?> poin</div><form method="post"><input type="hidden" name="csrf" value="<?php echo pm_e(customer_csrf());?>"><input type="hidden" name="reward_id" value="<?php echo (int)$r['id'];?>"><button class="btn" type="submit" onclick="return confirm('Tukar reward ini dengan poin Anda?')" <?php echo $balance<(int)$r['points_cost']?'disabled':'';?>>Tukar Reward</button></form></div></article><?php endforeach;endif;?><div class="tip">Aturan saat ini: setiap Rp<?php echo number_format((float)$settings['points_per_amount'],0,',','.');?> menghasilkan 1 poin<?php echo (float)$settings['points_per_order_min']>0?' setelah minimum belanja Rp'.number_format((float)$settings['points_per_order_min'],0,',','.'):'';?>.</div></section><section class="card"><h2>Riwayat Poin</h2><p class="desc">50 transaksi poin terbaru.</p><div class="history"><?php if(!$hist):?><div class="empty">Belum ada riwayat poin.</div><?php else:foreach($hist as $t):?><div class="tx"><div><strong><?php echo pm_e($t['description']);?></strong><small><?php echo date('d M Y, H:i',strtotime($t['created_at']));?> WIB</small></div><strong class="<?php echo $t['points']>0?'earn':'redeem';?>"><?php echo $t['points']>0?'+':'';?><?php echo number_format((int)$t['points'],0,',','.');?> poin</strong></div><?php endforeach;endif;?></div></section></div></main></body></html>
